import { test, expect } from '@playwright/test';

test.describe('Mark All Notifications as Read', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should mark all notifications as read with one click', async ({ page }) => {
    // Verify initial notification count
    const notificationCount = page.getByRole('heading', { name: /notifications/i }).count();
    await expect(notificationCount).toBeGreaterThan(0);

    // Verify notifications are visible
    const notifications = page.getByRole('region', { name: /notifications/i });
    await expect(notifications).toBeVisible();

    // Verify read button is disabled initially
    const readButton = page.getByRole('button', { name: /mark all as read/i });
    await expect(readButton).toBeDisabled();

    // Click read button
    await readButton.click();

    // Verify all notifications are marked as read
    const readStatus = page.getByText(/all read/i);
    await expect(readStatus).toBeVisible();

    // Verify read button is now enabled
    await expect(readButton).not.toBeDisabled();

    // Verify notification count is updated
    const updatedCount = page.getByRole('heading', { name: /notifications/i }).count();
    await expect(updatedCount).toBe(0);

    // Verify success message is displayed
    const successMessage = page.getByText(/all notifications have been marked as read/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle edge case when no notifications are present', async ({ page }) => {
    // Verify no notifications are present
    const notificationCount = page.getByRole('heading', { name: /notifications/i }).count();
    await expect(notificationCount).toBe(0);

    // Verify read button is disabled when no notifications are available
    const readButton = page.getByRole('button', { name: /mark all as read/i });
    await expect(readButton).toBeDisabled();

    // Verify success message is not displayed
    const successMessage = page.getByText(/all notifications have been marked as read/i);
    await expect(successMessage).not.toBeVisible();

    // Verify no error message is displayed
    const errorMessage = page.getByText(/no notifications to mark/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify read button is still enabled
    await expect(readButton).not.toBeDisabled();
  });
});
